// zip_add (deprecated): add a new file from a source under a given name.
// We create a fresh memory-backed source here so ownership transfer is clear and safe.
// Requirements:
// - za valid; name non-null/non-empty; source valid.
// Generate a small content buffer
std::string content = FUZZ_PARAM_STR();
if (content.size() > 2048) content.resize(2048);
const void *buf = content.data();
zip_uint64_t len = (zip_uint64_t)content.size();
int freep = 0; // we do not transfer ownership of our buffer
zip_source_t *src = zip_source_buffer(za, buf, len, freep);
if (!src) { FUZZ_BAIL(); }
// Name: ensure non-empty and avoid embedded null at start
std::string n = FUZZ_PARAM_STR();
if (n.empty()) { FUZZ_BAIL(); }
const char *name = n.c_str();
zip_int64_t idx = zip_add(za, name, src);
if (idx < 0) {
    // On failure, lib does not take ownership; free the source
    zip_source_free(src);
}
// za is returned to pool. src is either consumed by the archive or freed above.

// zip_add_dir (deprecated): add an empty directory entry.
// Ensure name resembles a directory (end with '/').
std::string d = FUZZ_PARAM_STR();
if (d.empty()) { d = "/"; }
if (d.back() != '/') d.push_back('/');
const char *dirname = d.c_str();
zip_int64_t idx = zip_add_dir(za, dirname);
(void)idx; // ignore result; archive retains changes until close

// zip_get_file_comment (deprecated): get comment by index.
// Requirements: index in range; optional length pointer may be NULL.
zip_int64_t n_entries = zip_get_num_entries(za, (zip_flags_t)0);
if (n_entries <= 0) { FUZZ_BAIL(); }
zip_uint64_t idx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)n_entries);
int flags = (int)(*FUZZ_PARAM(unsigned int));
int len_out_local = 0;
int *lenp = ((*FUZZ_PARAM(unsigned int)) % 2) ? &len_out_local : nullptr;
const char *c = zip_get_file_comment(za, idx, lenp, flags);
(void)c; (void)len_out_local;

// zip_get_num_files (deprecated): return number of entries as int
int n = zip_get_num_files(za);
// Record for downstream use
FUZZ_SET_ATTR_INT(za, "num_files_deprecated", n);

// zip_rename (deprecated): rename entry by index.
zip_int64_t n_entries = zip_get_num_entries(za, (zip_flags_t)0);
if (n_entries <= 0) { FUZZ_BAIL(); }
zip_uint64_t idx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)n_entries);
std::string newn = FUZZ_PARAM_STR();
if (newn.empty()) { FUZZ_BAIL(); }
int rc = zip_rename(za, idx, newn.c_str());
(void)rc;

// zip_replace (deprecated): replace entry data with content from a source.
// Create a standalone source from memory so we control ownership on failure.
std::string data = FUZZ_PARAM_STR();
if (data.size() > 2048) data.resize(2048);
zip_error_t *err_opt = nullptr; // not needed here
zip_source_t *src = zip_source_buffer_create(data.data(), (zip_uint64_t)data.size(), 0, err_opt);
if (!src) { FUZZ_BAIL(); }
zip_int64_t n_entries = zip_get_num_entries(za, (zip_flags_t)0);
if (n_entries <= 0) { zip_source_free(src); FUZZ_BAIL(); }
zip_uint64_t idx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)n_entries);
int rc = zip_replace(za, idx, src);
if (rc != 0) {
    // On failure, free our source to avoid leaks
    zip_source_free(src);
}
// On success, archive owns the source.

// zip_set_file_comment (deprecated): set/clear a comment by index.
zip_int64_t n_entries = zip_get_num_entries(za, (zip_flags_t)0);
if (n_entries <= 0) { FUZZ_BAIL(); }
zip_uint64_t idx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)n_entries);
// Randomly choose to clear or set
int clear = (int)(*FUZZ_PARAM(unsigned int) % 2);
const char *comment = nullptr;
int len = 0;
if (!clear) {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 65535) s.resize(65535);
    comment = s.c_str();
    len = (int)s.size();
}
int rc = zip_set_file_comment(za, idx, comment, len);
(void)rc;

// zip_error_init_with_code: initialize a standalone error object with a given libzip error code.
zip_error_t *err = new zip_error_t();
int code = (int)(*FUZZ_PARAM(unsigned int));
zip_error_init_with_code(err, code);
