char buf[256];
zip_uint64_t buflen = sizeof(buf);
int zip_err = (int)(*FUZZ_PARAM(unsigned int));
int sys_err = (int)(*FUZZ_PARAM(unsigned int));
int rc = zip_error_to_str(buf, buflen, zip_err, sys_err);
(void)rc; (void)buf;

// zip_file_error_get (deprecated): get last error codes for a zip_file stream.
int ze = 0, se = 0;
int *zep = ((*FUZZ_PARAM(unsigned int)) % 2) ? &ze : nullptr;
int *sep = ((*FUZZ_PARAM(unsigned int)) % 2) ? &se : nullptr;
zip_file_error_get(zf, zep, sep);
if (zep) { FUZZ_SET_ATTR_INT(zf, "last_zip_err", *zep); }
if (sep) { FUZZ_SET_ATTR_INT(zf, "last_sys_err", *sep); }

// zip_source_zip (deprecated): create a source in dst referencing data from src by index.
// Obtain a valid index from src
zip_int64_t nsrc = zip_get_num_entries(src, (zip_flags_t)0);
if (nsrc <= 0) { FUZZ_BAIL(); }
zip_uint64_t sidx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)nsrc);
// Retrieve size to bound offset/length
zip_stat_t st; zip_stat_init(&st);
if (zip_stat_index(src, sidx, (zip_flags_t)0, &st) != 0) { FUZZ_BAIL(); }
zip_uint64_t full = st.size;
zip_uint64_t start = 0;
zip_int64_t length = 0; // 0 will be treated as specific; use a bounded random range
if (full > 0) {
    start = (zip_uint64_t)(*FUZZ_PARAM(unsigned int)) % full;
    zip_uint64_t maxlen = full - start;
    // choose either ZIP_LENGTH_TO_END (-1) or a concrete length within bounds
    if (((*FUZZ_PARAM(unsigned int)) % 2) == 0) {
        length = (zip_int64_t)maxlen; // full to end
    } else {
        zip_uint64_t l = 1 + ((zip_uint64_t)(*FUZZ_PARAM(unsigned int)) % (maxlen));
        length = (zip_int64_t)l;
    }
}
zip_flags_t flags = (zip_flags_t)*FUZZ_PARAM(unsigned int);
zip_source_t *zs = zip_source_zip(dst, src, sidx, flags, start, length);
if (!zs) { FUZZ_BAIL(); }
// Return both archives and the created source

// zip_source_zip_create (deprecated): create a standalone source referencing entry in src archive.
zip_int64_t nsrc = zip_get_num_entries(src, (zip_flags_t)0);
if (nsrc <= 0) { FUZZ_BAIL(); }
zip_uint64_t sidx = (zip_uint64_t)((*FUZZ_PARAM(unsigned int)) % (zip_uint64_t)nsrc);
zip_stat_t st; zip_stat_init(&st);
