        length = (zip_int64_t)l;
    }
}
zip_flags_t flags = (zip_flags_t)*FUZZ_PARAM(unsigned int);
zip_error_t *errp = nullptr; // omit explicit error capture
zip_source_t *zs = zip_source_zip_create(src, sidx, flags, start, length, errp);
if (!zs) { FUZZ_BAIL(); }
// Return src and the new standalone source

// zip_close: close archive and commit changes. Do not return za to pool.
int rc = zip_close(za);
(void)rc; // result can be checked by surrounding sequences using zip_get_error() if needed
// After this call, za must not be used again; omit from outputs.

// zip_delete: delete entry by index.
