auto legacy_cb = +[](double progress){ (void)progress; };
int use_null = (int)(*FUZZ_PARAM(unsigned int) % 2);
// According to header, second parameter type is zip_progress_callback_t (aka void (*)(double))
void (*cb_to_set)(double) = use_null ? nullptr : legacy_cb;
zip_register_progress_callback(za, cb_to_set);
