FUZZ_ASSERT(e != nullptr, "zip_get_error must return non-null for valid archive");
// Record that we touched the error for potential downstream logic
FUZZ_SET_ATTR_INT(za, "has_error_obj", 1);
(void)e;

// zip_error_clear: clear archive error state.
zip_error_clear(za);
FUZZ_SET_ATTR_INT(za, "has_error_obj", 0);

